#pragma once
#include "kstationControllerDeviceState.h"
#include "kstationControllerInterruptRuntime.h"
#include "kstationStartupHardwareTask.h"
#include <variant>
namespace kstation {
class ControllerStartupHardwareRuntime final {
 using I=StartupInterruptSetupTask;using T=StartupTimerSetupTask;using P=StartupPwmTask;using S=StartupSerialSetupTask;struct Job{std::variant<I,T,P,S>task;};
public:
 enum class Kind:uint8_t{Interrupts,Timers,Pwm,Serial};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};struct Range{uint32_t begin,end;};inline static constexpr std::array<Range,2>CodeRanges{{{0x830,0x8ba},{0x9b6,0x9d0}}};
 bool bindBootResources(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin))return false;bound_=&d;return true;}
 bool bindMirroredFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_!=&d||mirrored_||!image||size!=49728||!d.hasImmutableCapacity(CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;mirrored_=true;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return depth_!=0;}void reset(){depth_=0;}
 bool start(Kind kind,uint8_t value=0){if(!bound_||active())return false;auto&j=jobs_[depth_++];switch(kind){case Kind::Interrupts:j.task.emplace<I>();break;case Kind::Timers:j.task.emplace<T>();break;case Kind::Pwm:j.task.emplace<P>(value);break;case Kind::Serial:j.task.emplace<S>();break;}return true;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq)const{if(bound_!=&d||!active()||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(!irq.boundTo(d)&&irq.mask()!=ControllerInterruptRuntime::Mask::Disabled)||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return 0;auto cr=credits(d);auto n=std::visit([&](const auto&t){return t.nextClocks(cr);},jobs_[depth_-1].task);return n?n+(d.pendingIrqs?1u:0u):0;}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,unsigned available){if(bound_!=&d)return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(!irq.boundTo(d)&&irq.mask()!=ControllerInterruptRuntime::Mask::Disabled)||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};auto total=nextClocks(d,irq);if(!total||available<total)return {};auto arb=d.pendingIrqs?1u:0u;if(arb)(void)d.read8(0xfffff2);auto clocks=total-arb;auto begin=d.cycles;auto&j=jobs_[depth_-1];auto cr=credits(d);bool child=false,stack=false,done=false;
 std::visit([&](auto&t){using X=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<X,T>){child=t.stage()==T::Stage::PwmChild;stack=child;check(t.advanceBefore(clocks,cr,[&](unsigned a,unsigned width,unsigned value){d.cycles=begin+(width==4?6u:3u);write(d,a,width,value);})==clocks);}else if constexpr(std::is_same_v<X,P>){check(t.advanceBefore(clocks,cr,[&](unsigned value){d.cycles=begin+3;d.write8(0xffff6c,uint8_t(value));})==clocks);}else{if constexpr(std::is_same_v<X,S>)stack=t.stage()==S::Stage::Retain;check(t.advanceBefore(clocks,cr,[&](unsigned a,unsigned value){d.cycles=begin+3;d.write8(a,uint8_t(value));})==clocks);}done=t.complete();},j.task);
 d.cycles=begin+clocks;d.lastRead=-1;if(stack)d.lastWrite=-1;if(child){if(depth_==jobs_.size())throw std::logic_error("K startup hardware capacity");jobs_[depth_++].task.emplace<P>(0x40);}else if(done){--depth_;if(depth_)std::get<T>(jobs_[depth_-1].task).resume();}return {total,depth_==0,Block::None};}
private:static void check(bool p){if(!p)throw std::logic_error("K domain startup hardware phase");}static void write(ControllerDeviceState&d,unsigned a,unsigned width,unsigned value){for(unsigned i=0;i<width;++i)d.write8(a+i,uint8_t(value>>(8*(width-i-1))));}static unsigned bus(unsigned a,unsigned width,int last){unsigned n=0;for(unsigned i=0;i<width;++i){auto p=(a+i)&0xffffff;if(p<0x400000||(p>=0xfffd10&&p<0xffffa0)){if((last&1)||p!=unsigned(last|1))n+=p<0x400000?3:1;last=int(p);}else{n+=p>=0xffffa0?1:3;last=-1;}}return n;}
 FlashCredits credits(const ControllerDeviceState&d)const{FlashCredits cr;cr.pushWord=cr.popWord=6;cr.shortCall=5;cr.ret=7;cr.write=1;if(auto*t=std::get_if<T>(&jobs_[depth_-1].task))cr.write=bus(t->address(),t->width(),d.lastWrite);return cr;}
 ControllerDeviceState*bound_=nullptr;bool mirrored_=false;std::array<Job,2>jobs_{};unsigned depth_=0;
};
}
